package com.bank.portfolio;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class MomentumAnalyzer {

    private static final Logger log = Logger.getLogger(MomentumAnalyzer.class.getName());

    public int longestIncreasing(int[] prices) {
        List<Integer> tails = new ArrayList<>();       // smallest tail per length
        for (int x : prices) {
            int pos = lowerBound(tails, x);            // first tail >= x
            if (pos == tails.size()) {
                tails.add(x);                          // x extends the longest run
            } else {
                tails.set(pos, x);                     // tighter tail keeps it extendable
            }
        }
        int result = tails.size();
        log.info(() -> "Longest increasing run length = " + result);
        return result;
    }

    private int lowerBound(List<Integer> tails, int x) {
        int lo = 0, hi = tails.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (tails.get(mid) < x) lo = mid + 1;      // strictly increasing ⇒ lower bound
            else hi = mid;
        }
        return lo;
    }
}
