package com.bank.portfolio;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class LisDemo {

    private static final Logger log = Logger.getLogger(LisDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Portfolio Momentum Analyzer (LIS)");
        MomentumAnalyzer analyzer = new MomentumAnalyzer();
        int[] prices = {10, 9, 2, 5, 3, 7, 101, 18};
        log.info("prices → LIS = " + analyzer.longestIncreasing(prices)); // 4 (2,3,7,18)
    }
}
